import org.openenglish.reader.*;import java.util.*;import java.util.concurrent.*;
public final class IslandDialogueModelsTest {
 static int checks;static void check(boolean b,String n){if(!b)throw new AssertionError(n);checks++;System.out.println("PASS "+n);}
 static class Call implements LocalNative.Callbacks{int deltas;boolean stop;String last="";public boolean abort(){return stop;}public void text(String s){deltas++;last=s;}public void segment(long a,long b,String s){}}
 public static void main(String[] args)throws Exception {LocalNative.loadLlama();for(int model=0;model<2;model++){for(String code:new String[]{"yue","ja","zh"}){String input=code.equals("yue")?"唔該，我想飲凍奶茶。":code.equals("ja")?"こんにちは。コーヒーをひとつください。":"你好，我想要一杯咖啡。";List<String[]> h=Collections.singletonList(new String[]{"user",input});String instruction=IslandPrompt.instruction(code,"咖啡店店员","偏好：少甜，慢一点。"),prompt=model==0?IslandPrompt.qwen(instruction,h):IslandPrompt.deepseek(instruction,h);Call call=new Call();long start=System.nanoTime();String raw=LocalNative.chat(args[model],prompt,3,120,call),reply=LocalPrompt.visible(raw);System.out.println((model==0?"QWEN_1_5 ":"DEEPSEEK ")+code+": "+reply+" HOST_MS="+(System.nanoTime()-start)/1000000);check(!reply.isEmpty()&&call.deltas>0,"real selected model streams "+model+" "+code);check(LocalPrompt.visible(call.last).equals(reply),"complete streamed response consistent "+model+" "+code);check(!reply.contains("<think>"),"private reasoning excluded "+model+" "+code);}check(LocalNative.llamaLoadCount()==model+1,"selected model warm cache reused "+model);}
 Call stop=new Call(){public void text(String s){super.text(s);this.stop=true;}};boolean cancelled=false;try{LocalNative.chat(args[1],IslandPrompt.deepseek(IslandPrompt.instruction("zh","聊天",""),Collections.singletonList(new String[]{"user","请问你好。"})),3,120,stop);}catch(CancellationException e){cancelled=true;}check(cancelled&&stop.deltas==1,"barge-in stops active multilingual generation");LocalNative.releaseLlama();System.out.println("ISLAND_DIALOGUE_MODEL_CHECKS: "+checks);}
}
